#include <bits/stdc++.h>
using namespace std;
const int M=998244353;
int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<vector<int>> g(n+1);
        for(int i=1; i<=n;i++){
            int x;
            cin>>x;
            g[x].push_back(i);
            
        }
        vector<int> d(n+2,0), e(n+2);
        d[0]=1;
        for(int v=1; v<=n; v++){
            fill(e.begin(), e.end(), 0);
            for(int l=0; l<v;l++){
                if(!d[l]) continue;
                int r=v-1-l;
                for(int s=0;s<2;s++){
                    if(v==n&&s) continue;
                    int p=s?n-r:l+1;
                    bool ok=true;
                    for(int i: g[v]){
                        bool f=false;
                        if(p<=i){
                            int c=min(l,i)+max(0,i-(n-r));
                            f=(c==(i+1)/2-1);
                        }
                        if(!f&&p>=i){
                            int m=n-i+1;
                            int c=max(0,l-i+1) + min(r,m);
                            f=(c==(m+1)/2-1);
                        }
                        if(!f) {
                            ok=false;
                            break;
                        }
                    }
                    if(ok){
                        int &z= e[l+(s?0:1)];
                        z+=d[l];
                        if(z>=M) z-=M;
                    }
                }
            }
            swap(d,e);
        }
        long long ans=0;
        for(int x:d) ans+=x;
        cout<< ans%M<<endl;
    }
    return 0;
}
